func fanOut(items []string) {
    var wg sync.WaitGroup
    for _, item := range items {
        wg.Add(1)
        go func(item string) {       // pass item as arg (pre-1.22 safe)
            defer wg.Done()
            process(item)
        }(item)
    }
    wg.Wait()
}

