func Map[T, U any](s []T, f func(T) U) []U {
    out := make([]U, len(s))
    for i, v := range s {
        out[i] = f(v)
    }
    return out
}

func Filter[T any](s []T, keep func(T) bool) []T {
    out := s[:0:0] // nil slice
    for _, v := range s {
        if keep(v) {
            out = append(out, v)
        }
    }
    return out
}

